param([Parameter(Mandatory=$true)][ValidateSet('CPU','GPU')][string]$Backend,[ValidateSet('1','8')][string]$Threads,[Parameter(Mandatory=$true)][string]$PublicStageReceipt,[switch]$ExecutionAuthorized)
# One sequential controlled-cost public Release project-main call. No build, decoder or next job.
$ErrorActionPreference='Stop';$Backend=$Backend.ToUpperInvariant();$Window='coarse';$jobName=if($Backend -ceq 'CPU'){'cpu'+$Threads}else{'gpu'};$threadCount=if($Backend -ceq 'CPU'){[int]$Threads}else{$null}
$cfg=if($Backend -ceq 'CPU'){'ReleaseCPU'}else{'Release'}
$tests=Split-Path -Parent $PSScriptRoot;$repo=(Get-Item -LiteralPath $tests).Parent.Parent.Parent.Parent.FullName;$logs=Join-Path $tests 'logs';$src=Join-Path $repo 'src';$tag='upl_column_cost_r1_'+$jobName
$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($r in $rows){Need ($r.path -and $null -ne $r.bytes -and $r.sha256) 'Missing bound Entry';$a=E $r.path;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) ('Changed bound artifact: '+$r.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$value){Fresh @($p);[IO.File]::WriteAllText($p,($value|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function Owned($entry){V @($entry);$c=J $entry.path;Need ($c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Owned typed exit0 required';V @($c.program,$c.log)}
function SameEntry($a,$b){return ($a.path -ieq $b.path -and $a.bytes -eq $b.bytes -and $a.sha256 -ieq $b.sha256)}
Need $ExecutionAuthorized.IsPresent 'Explicit ExecutionAuthorized required';Need ($(if($Backend -ceq 'CPU'){$Threads -cin @('1','8')}else{[string]::IsNullOrWhiteSpace($Threads)})) 'CPU requires Threads1/8; GPU must omit Threads';Fresh @($folder,$record,$callPath,$log)
$buildPath=Join-Path $logs ('upl_column_public_'+$cfg+'_r1.build.json');$buildEntry=E $buildPath;$b=J $buildPath
Need ($b.passed -and $b.configuration -ceq $cfg -and !$b.helper_built -and !$b.canonical_program_installed) 'Passed isolated authoritative project-main build required'
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_cost_r1.json')),$buildEntry);$sourceFreeze=$null;$adoptedCPU=$null
if($Backend -ceq 'CPU'){
  Need ($b.direct_native_call -and $b.typed_LASTEXITCODE_captured_immediately -and $b.owned_call_exited -and $b.exit_code -is [int] -and $b.exit_code -eq 0 -and $b.source_bindings_unchanged -and $b.canonical_programs_unchanged -and @($b.objects).Count -eq 86) 'Current CPU build top-level typed exit/source/object gate rejected'
  $adoptedCPU=$b.adopted_Debug_source_build;V @($adoptedCPU);$cpu=J $adoptedCPU.path;$bindings+=@($adoptedCPU);Need ($cpu.passed -and $cpu.configuration -ceq 'DebugCPU' -and $cpu.source_bindings_unchanged -and $cpu.runtime_unchanged) 'Release adopts the same-round Debug documentation/runtime identities'
  $pairs=@($b.source_snapshot);$doc=$cpu.documentation_snapshot;$canonical=@($b.canonical_programs_before);$runtimeBefore=@($cpu.runtime_before);$program=$b.program
}else{
  Need ($b.status -ceq 'full_authoritative_GPU_Rebuild_passed_no_helper_or_program_run' -and $b.source_and_protected_artifacts_unchanged -and $b.canonical_programs_unchanged -and $b.objects_exclude_main -and @($b.objects).Count -eq 110 -and @($b.runtime).Count -eq 4 -and !$b.program_or_component_run) 'Current authoritative GPU110/main build rejected'
  Owned $b.project_call;$sourceFreeze=$b.source_freeze;V @($sourceFreeze);$s=J $sourceFreeze.path;$pairs=@($s.current_source_snapshot);$doc=$s.documentation_snapshot;$canonical=@($s.canonical_programs_before);$runtimeBefore=@($s.runtime_before);$program=$b.isolated_GPU_program
  Need (@($s.source).Count -eq 265) 'Current GPU source265 required';$bindings+=@($sourceFreeze,$b.project_call,$b.project_main_object)+@($b.inputs)+@($s.source)
}
Need ($pairs.Count -eq 265 -and @($pairs.original.path|Sort-Object -Unique).Count -eq 265 -and $canonical.Count -eq 7 -and $runtimeBefore.Count -eq 4 -and $doc.original.path -and $doc.snapshot.path) 'Current265/doc/canonical7/runtime4 closure required'
foreach($row in $pairs){Need ($row.original.bytes -eq $row.snapshot.bytes -and $row.original.sha256 -ieq $row.snapshot.sha256) 'Source original/snapshot identity differs';$bindings+=@($row.original,$row.snapshot)}
$bindings+=@($doc.original,$doc.snapshot,$program)+$canonical+$runtimeBefore+@($b.objects)+@($b.tools);if($Backend -ceq 'CPU'){$bindings+=@($b.author_files)}
$manifestPath=Join-Path $logs 'upl_column_public_r1.inputs.json';$manifest=J $manifestPath;Need ($manifest.stage -ceq 'upl_column_public_prepare_r1' -and $manifest.prepared -and $manifest.passed -and $manifest.physical_acceptance -eq $false -and @($manifest.jobs).Count -eq 3) 'Own prepared public-input manifest required'
$jobs=@($manifest.jobs|Where-Object {$_.window -ceq $Window});Need ($jobs.Count -eq 1) 'One exact public window input required';$job=$jobs[0]
$steps=10000;$samples=769;$dt=2.5e-6;$end=0.025
Need ($job.physical_XML_equal_except_master -eq $true -and $job.backend_shared_runtime -eq $true -and $job.master_value -eq 1 -and $job.conductivity_model -eq 0 -and $job.conductivity_Ck -eq 0 -and !$job.initial_particle_fields_rewritten -and $job.runtime.sha256 -ceq '3d166d2825f9be0d594f22f4d0e2a3b10eb6cf058d08db591eb78f3e39d0cb77' -and $job.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $job.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97' -and $job.dt_s -eq $dt -and $job.end_s -eq $end -and $job.steps -eq $steps -and $job.expected_samples -eq $samples) 'Declared public master-only input/window differs'
$prefix=Join-Path (Split-Path -Parent $job.runtime.path) ([IO.Path]::GetFileNameWithoutExtension($job.runtime.path));Need ([IO.Path]::GetExtension($job.runtime.path) -ceq '.xml' -and ($prefix+'.xml') -ceq $job.runtime.path -and $prefix -ceq $job.input_prefix) 'Exact runtime XML prefix reconstruction rejected'
$bindings+=@((E $manifestPath),$job.configuration,$job.runtime,$job.initial_BI4,$job.normals)+@($manifest.inputs)+@($manifest.bindings)+@($manifest.files)
$publicStage=E $PublicStageReceipt;$review=J $publicStage.path;Need ($review.stage -ceq 'upl_column_public_root_r1' -and $review.passed_implementation_review -and $review.physical_acceptance -eq $false -and @($review.primary_receipts).Count -eq 14) 'Bounded public root implementation review required'
$publicProofs=@();foreach($relative in $review.primary_receipts){$e=E (Join-Path $tests $relative);Need ((J $e.path).passed -eq $true) 'Public primary proof not passed';$publicProofs+=@($e)};$bindings+=@($publicStage)+$publicProofs
$admission=E (Join-Path $logs 'upl_column_cost_r1.admission.json');$gate=J $admission.path;Need ($gate.stage -ceq 'upl_column_cost_admission_r1' -and $gate.passed -and $gate.physical_acceptance -eq $false -and @($gate.inputs).Count -gt 0) 'Future root cost admission after OFF half/review required';V $gate.inputs;$bindings+=@($admission)+@($gate.inputs)
$priorRuns=@();$priorNative=@();$priorNames=@();if($jobName -ceq 'cpu8'){$priorNames=@('cpu1')}elseif($jobName -ceq 'gpu'){$priorNames=@('cpu1','cpu8')}
$sourceByPath=@{};foreach($row in $pairs){$sourceByPath[$row.original.path]=$row.original}
foreach($name in $priorNames){
  $pr=E (Join-Path $logs ('upl_column_cost_r1_'+$name+'.run.json'));$pn=E (Join-Path $logs ('upl_column_cost_r1_'+$name+'.native.json'));$p=J $pr.path;$q=J $pn.path
  Need ($p.passed -and $p.stage -ceq 'upl_column_cost_r1' -and $p.job -ceq $name -and $p.backend -ceq 'CPU' -and $p.window -ceq 'coarse' -and $p.threads -eq $(if($name -ceq 'cpu1'){1}else{8}) -and $p.source_inputs_objects_runtime_canonical_unchanged -and $p.no_other_project_process_observed_at_boundaries -and (SameEntry $p.runtime_input $job.runtime) -and (SameEntry $p.cost_admission_receipt $admission)) 'Own sequential prior cost Run rejected'
  Need ($q.passed -and $q.stage -ceq 'upl_column_cost_native_r1' -and $q.job -ceq $name -and $q.backend -ceq 'CPU' -and $q.physical_acceptance -eq $false -and $q.source_inputs_raw_objects_runtime_canonical_unchanged -and $q.drainage_nonempty_per_frame_independently_verified -and (SameEntry $q.source_run $pr)) 'Prior own cost native safety/source_run required'
  Owned $p.call;Owned $q.reader_call;V @($q.completion);$done=J $q.completion.path;Need ($done.passed -and $done.stage -ceq 'upl_column_public_native_r1' -and $done.backend -ceq 'CPU_public' -and $done.window -ceq 'window25' -and $done.samples -eq 769 -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.native_total_arrays -eq 22 -and $done.PART_typed_public_metadata_verified -and $done.no_exclusions -and $done.all_exported_physical_fields_finite -and $done.physical_acceptance -eq $false) 'Prior actual public22 native guard rejected'
  Need (@($p.source_snapshot).Count -eq 265) 'Prior cost source265 missing';foreach($row in $p.source_snapshot){Need ($sourceByPath.ContainsKey($row.original.path) -and (SameEntry $sourceByPath[$row.original.path] $row.original)) 'Prior/current cost source differs'}
  V $p.inputs;V $p.files;V $q.inputs;V $q.files;$bindings+=@($pr,$pn,$p.call,$q.reader_call,$q.completion)+@($p.files)+@($q.files);$priorRuns+=@($pr);$priorNative+=@($pn)
}
V $bindings
$runtime=@();$exeDir=Split-Path -Parent $program.path
if($Backend -ceq 'CPU'){
  foreach($r in $runtimeBefore){$dest=Join-Path $exeDir ([IO.Path]::GetFileName($r.path));$copied=$false;if(Test-Path -LiteralPath $dest){$a=E $dest;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) 'Existing CPU runtime differs; do not overwrite'}else{Copy-Item -LiteralPath $r.path -Destination $dest;$copied=$true};$a=E $dest;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) 'CPU runtime copy differs';$runtime+=@{original=$r;copy=$a;copied_by_this_action=$copied}}
}else{foreach($row in $b.runtime){$matchesRuntime=@($runtimeBefore|Where-Object {[IO.Path]::GetFileName($_.path) -ieq [IO.Path]::GetFileName($row.copy.path)});Need ($matchesRuntime.Count -eq 1 -and $matchesRuntime[0].bytes -eq $row.copy.bytes -and $matchesRuntime[0].sha256 -ieq $row.copy.sha256 -and (Split-Path -Parent $row.copy.path) -ieq $exeDir) 'Built GPU runtime identity/directory differs';$runtime+=@($row)}}
Need ($runtime.Count -eq 4) 'Exactly four executable-directory runtime files required'
$targetArgs=@(if($Backend -ceq 'CPU'){'-cpu';('-ompthreads:'+$Threads)}else{'-gpu:0'});$targetArgs+=@('-stable','-mdbc_freeslip',$prefix,$folder,'-dirdataout','data','-svres',('-nsteps:'+$steps))
function Verify{V $bindings;foreach($row in $runtime){V @($row.original,$row.copy)}}
function ProcessAudit{
  $active=@(Get-CimInstance -ClassName Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe'" -ErrorAction Stop|ForEach-Object{[ordered]@{name=$_.Name;pid=$_.ProcessId;executable_path=$_.ExecutablePath;command_line=$_.CommandLine;creation_date=[string]$_.CreationDate}})
  return [ordered]@{observed_utc=[DateTime]::UtcNow.ToString('o');query="Win32_Process: DualSPHysics*.exe or upl_*.exe";processes=$active;none_observed=($active.Count -eq 0)}
}
function Seconds([string]$text,[string]$label){$m=[regex]::Matches($text,('(?m)^'+[regex]::Escape($label)+'[.]+:\s*([0-9]+(?:\.[0-9]+)?)\s+sec[.]\s*$'));Need ($m.Count -eq 1) ('Missing/ambiguous actual timing: '+$label);$v=[double]::Parse($m[0].Groups[1].Value,[Globalization.CultureInfo]::InvariantCulture);Need (![double]::IsNaN($v) -and ![double]::IsInfinity($v) -and $v -gt 0) 'Invalid actual runtime';return $v}
Verify
[IO.File]::WriteAllBytes($log,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$beforeAudit=$null;$afterAudit=$null;$attempted=$false;$wallSeconds=$null;$watch=New-Object Diagnostics.Stopwatch
try{$beforeAudit=ProcessAudit;Need $beforeAudit.none_observed 'No call: another project main/helper process is active'}catch{$launchFailure=$_.Exception.Message}
if(!$launchFailure){$saved=$ErrorActionPreference;Push-Location $src;try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;$attempted=$true;$watch.Start();& $program.path @targetArgs 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{$watch.Stop();$wallSeconds=$watch.Elapsed.TotalSeconds;Pop-Location;$ErrorActionPreference=$saved}}
$ended=[DateTime]::UtcNow.ToString('o');try{$afterAudit=ProcessAudit}catch{if(!$launchFailure){$launchFailure=$_.Exception.Message}}
Save $callPath ([ordered]@{program=$program;target_program=$program;arguments=$targetArgs;target_arguments=$targetArgs;working_directory=$src;started_utc=$started;ended_utc=$ended;direct_native_call=$attempted;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);public_project_main=$true;fixture_or_Run_override=$false;memcheck_executed=$false;direct_target_call=$true;target_child_exit_separately_observed=$false;invocation_wall_seconds_including_Tee=$wallSeconds;process_audit_before=$beforeAudit;process_audit_after=$afterAudit;physical_acceptance=$false})
# The actual typed call is immutable before inspecting or hashing any solver output.
$failure=$launchFailure;$unchanged=$false;$files=@();$rawExact=$false;$runOut=$null;$rawCount=0;$simulationSeconds=$null;$totalSeconds=$null;$actualMode=$null;$processQuiet=($beforeAudit -and $beforeAudit.none_observed -and $afterAudit -and $afterAudit.none_observed)
try{
  Need ($attempted -and $code -is [int] -and $code -eq 0 -and !$launchFailure -and $processQuiet) 'Owned cost exit/process boundary audit rejected'
  $runOut=E (Join-Path $folder 'Run.out');$runText=[IO.File]::ReadAllText($runOut.path);Need ($runText -match '(?m)^\[Simulation finished\s') 'Actual normal completion missing';$simulationSeconds=Seconds $runText 'Simulation Runtime';$totalSeconds=Seconds $runText 'Total Runtime'
  $modeMatches=[regex]::Matches($runText,'(?m)^RunMode=.*$');Need ($modeMatches.Count -eq 1) 'Exactly one actual RunMode required';$actualMode=$modeMatches[0].Value.Trim()
  if($Backend -ceq 'CPU'){if($threadCount -eq 1){Need ($actualMode -match 'Single core') 'Actual CPU1 Single core mode missing'}else{Need ($actualMode -match 'OpenMP\(Threads:8\)' -and $runText -match '(?m)^Threads by host for parallel execution:\s*8\s*$') 'Actual CPU8 OpenMP/thread-count mode missing'}}else{Need ($runText -match '(?m)^\[GPU Hardware\]\s*$' -and $runText -match '(?m)^\[GPU Timers\]\s*$') 'Actual GPU hardware/timer sections missing'}
  $raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$rawCount=$raw.Count;$expected=@(0..($samples-1)|ForEach-Object {'Part_{0:D4}.bi4' -f $_});$names=@($raw|ForEach-Object {$_.Name});$rawExact=($raw.Count -eq $samples -and @(Compare-Object ($names|Sort-Object) ($expected|Sort-Object)).Count -eq 0);Need $rawExact 'Native saved frame sequence/count differs; pure reader review is still required'
}catch{$failure=$_.Exception.Message}
try{Verify;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
if(Test-Path -LiteralPath $folder){$files=@(Get-ChildItem -LiteralPath $folder -File -Recurse|Sort-Object FullName|ForEach-Object {E $_.FullName})}
$passed=(!$failure -and $unchanged -and $rawExact -and $null -ne $runOut -and $code -is [int] -and $code -eq 0)
Save $record ([ordered]@{stage='upl_column_cost_r1';passed=[bool]$passed;job=$jobName;backend=$Backend;threads=$threadCount;window=$Window;configuration=$cfg;inputs=$bindings;source_build=$buildEntry;source_freeze=$sourceFreeze;adopted_Debug_source_build=$adoptedCPU;program=$program;input_manifest=(E $manifestPath);runtime_input=$job.runtime;input_prefix=$prefix;call=(E $callPath);arguments=$targetArgs;runtime=$runtime;canonical_programs_before=$canonical;source_snapshot=$pairs;documentation_snapshot=$doc;files=$files;run_out=$runOut;planned_steps=$steps;planned_samples=$samples;planned_dt_s=$dt;planned_end_s=$end;native_frames=$rawCount;native_frame_sequence_exact=$rawExact;public_stage_receipt=$publicStage;cost_admission_receipt=$admission;prior_cost_runs=$priorRuns;prior_cost_native_checks=$priorNative;process_audit_before=$beforeAudit;process_audit_after=$afterAudit;no_other_project_process_observed_at_boundaries=[bool]$processQuiet;continuous_process_monitoring_performed=$false;whole_machine_quiescence_guaranteed=$false;invocation_wall_seconds_including_Tee=$wallSeconds;simulation_runtime_seconds_reported=$simulationSeconds;total_runtime_seconds_reported=$totalSeconds;actual_RunMode=$actualMode;timing_excludes_preflight_and_post_hashing=$true;one_repetition_only=$true;native_decoder_or_QC_invoked=$false;source_inputs_objects_runtime_canonical_unchanged=$unchanged;all_raw_outputs_hash_bound=$true;public_project_main=$true;fixture_or_Run_override=$false;private_actual_complete_required=$false;solver_backend_proved_by_program_build_and_arguments=$true;completed_steps_or_actual_end_verified_by_this_owner=$false;CPU8_cross_thread_exactness_assumed=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Cost Run rejected; retain record/partials, no automatic retry"};Write-Output "One controlled-cost job sealed; own native safety remains separate: $record"
